files.content:
[hidden] { display: none !important; }

:root {
  --bg: #1b1b2f;
  --card: #23233f;
  --panel: #2e2e52;
  --accent: #ffd166;
  --accent-press: #e6b84d;
  --text: #f4f4f9;
  --muted: #a7a7c4;
  --danger: #ff6b6b;
  --focus: #7bdff2;
}

* { box-sizing: border-box; }

body {
  margin: 0;
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 24px 16px;
  background: var(--bg);
  background-image:
    linear-gradient(rgba(255,255,255,0.03) 1px, transparent 1px),
    linear-gradient(90deg, rgba(255,255,255,0.03) 1px, transparent 1px);
  background-size: 24px 24px;
  color: var(--text);
  font-family: system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
  font-size: 16px;
  line-height: 1.5;
}

.card {
  width: 100%;
  max-width: 560px;
  background: var(--card);
  border: 3px solid var(--panel);
  border-radius: 12px;
  padding: 24px;
  box-shadow: 0 8px 0 rgba(0,0,0,0.35);
}

.card-header h1 {
  margin: 0 0 4px;
  font-size: 1.6rem;
  letter-spacing: 0.5px;
}

.subtitle {
  margin: 0 0 20px;
  color: var(--muted);
}

.log-form {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: flex-end;
  margin-bottom: 20px;
}

.field {
  display: flex;
  flex-direction: column;
  gap: 6px;
  flex: 1 1 200px;
  min-width: 0;
}

.minutes-field { flex: 0 1 120px; }

label {
  font-size: 0.95rem;
  color: var(--muted);
}

input {
  font: inherit;
  padding: 10px 12px;
  border-radius: 8px;
  border: 2px solid var(--panel);
  background: var(--bg);
  color: var(--text);
  width: 100%;
}

input::placeholder { color: #6f6f92; }

input:hover { border-color: var(--accent); }
input:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
  border-color: var(--focus);
}

.btn {
  font: inherit;
  font-weight: 600;
  cursor: pointer;
  border-radius: 8px;
  padding: 10px 18px;
  border: 2px solid transparent;
  transition: transform 0.05s ease, background 0.15s ease;
}

.btn-primary {
  background: var(--accent);
  color: #1b1b2f;
  align-self: flex-end;
}

.btn-primary:hover { background: #ffe08a; }
.btn-primary:active { background: var(--accent-press); transform: translateY(2px); }
.btn-primary:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

.error {
  flex-basis: 100%;
  margin: 0;
  color: var(--danger);
  font-size: 0.95rem;
}

.summary {
  display: flex;
  gap: 12px;
  margin-bottom: 24px;
}

.stat {
  flex: 1;
  background: var(--panel);
  border-radius: 10px;
  padding: 12px 16px;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.stat-label {
  font-size: 0.85rem;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.6px;
}

.stat-value {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--accent);
}

.entries-section h2 {
  font-size: 1.1rem;
  margin: 0 0 12px;
}

.empty-state {
  color: var(--muted);
  margin: 0;
}

.entries-list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.entry {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--panel);
  border-radius: 10px;
  padding: 10px 12px;
}

.entry-text {
  flex: 1;
  min-width: 0;
  word-break: break-word;
  overflow-wrap: anywhere;
}

.entry-minutes {
  color: var(--accent);
  font-weight: 700;
  white-space: nowrap;
}

.btn-delete {
  background: transparent;
  color: var(--danger);
  border: 2px solid var(--danger);
  padding: 6px 12px;
  font-size: 0.9rem;
  flex-shrink: 0;
}

.btn-delete:hover { background: rgba(255,107,107,0.15); }
.btn-delete:active { transform: translateY(2px); background: rgba(255,107,107,0.25); }
.btn-delete:focus-visible {
  outline: 3px solid var(--focus);
  outline-offset: 2px;
}

@media (max-width: 420px) {
  .card { padding: 18px; }
  .summary { flex-direction: column; }
  .minutes-field { flex: 1 1 100%; }
  .btn-primary { width: 100%; }
}

(function () {
  "use strict";

  var entries = [];
  var nextId = 1;

  var form = document.getElementById("log-form");
  var taskInput = document.getElementById("task-input");
  var minutesInput = document.getElementById("minutes-input");
  var errorEl = document.getElementById("form-error");
  var listEl = document.getElementById("entries-list");
  var emptyEl = document.getElementById("empty-state");
  var totalEl = document.getElementById("total-minutes");
  var longestEl = document.getElementById("longest-session");

  function showError(message) {
    errorEl.textContent = message;
    errorEl.hidden = false;
  }

  function clearError() {
    errorEl.textContent = "";
    errorEl.hidden = true;
  }

  function render() {
    listEl.textContent = "";

    entries.forEach(function (entry) {
      var li = document.createElement("li");
      li.className = "entry";

      var text = document.createElement("span");
      text.className = "entry-text";
      text.textContent = entry.text;

      var minutes = document.createElement("span");
      minutes.className = "entry-minutes";
      minutes.textContent = entry.minutes + " min";

      var del = document.createElement("button");
      del.type = "button";
      del.className = "btn btn-delete";
      del.textContent = "Delete";
      del.setAttribute("aria-label", "Delete entry: " + entry.text);
      del.dataset.id = String(entry.id);

      li.appendChild(text);
      li.appendChild(minutes);
      li.appendChild(del);
      listEl.appendChild(li);
    });

    emptyEl.hidden = entries.length > 0;

    var total = entries.reduce(function (sum, e) { return sum + e.minutes; }, 0);
    var longest = entries.reduce(function (max, e) { return Math.max(max, e.minutes); }, 0);
    totalEl.textContent = String(total);
    longestEl.textContent = String(longest);
  }

  function addEntry(text, minutes) {
    entries.push({ id: nextId++, text: text, minutes: minutes });
    render();
  }

  form.addEventListener("submit", function (event) {
    event.preventDefault();
    clearError();

    var text = taskInput.value.trim();
    if (text === "") {
      showError("Please describe what you worked on.");
      taskInput.focus();
      return;
    }

    var minutes = Number(minutesInput.value);
    if (!Number.isInteger(minutes) || minutes < 1 || minutes > 1440) {
      showError("Enter whole minutes between 1 and 1440.");
      minutesInput.focus();
      return;
    }

    addEntry(text, minutes);
    form.reset();
    taskInput.focus();
  });

  listEl.addEventListener("click", function (event) {
    var btn = event.target.closest("button.btn-delete");
    if (!btn) return;
    var id = Number(btn.dataset.id);
    entries = entries.filter(function (e) { return e.id !== id; });
    render();
  });

  render();
})();
